// =============================================================================
// JustJoin.it Scraper — n8n Code Node (JavaScript)
// Metoda: HTML scraping + Next.js App Router RSC chunks (self.__next_f)
// Interfejs: executeWorkflowTrigger → { max_pages?, config? }
// =============================================================================

const DEFAULT_CONFIG = {
  maxPages: null,
  delayMs:  1200,
  category: null,   // np. "javascript" | "backend" | "mobile" | "devops"
  location: null,   // np. "warszawa" | "remote" | "krakow" | "all-locations"
};

// ── Helpers ──────────────────────────────────────────────────────────────────
function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function normalizeSeniority(level) {
  if (!level) return null;
  const map = {
    expert:   "expert",
    lead:     "lead",
    senior:   "senior",
    mid:      "mid",
    regular:  "mid",
    junior:   "junior",
    trainee:  "junior",
    intern:   "junior",
    c_level:  "c_level",
    manager:  "lead",
  };
  return map[level.toLowerCase()] ?? level.toLowerCase();
}

function parseWorkplaceType(raw) {
  if (!raw) return "office";
  const t = raw.toLowerCase().replace(/[-_]/g, "");
  if (["remote", "fullyremote", "online"].includes(t))    return "remote";
  if (["hybrid", "partiallyremote", "mixed"].includes(t)) return "hybrid";
  return "office";
}

// JJit employmentTypes: płaska tablica { from, to, currency, currencySource, type, unit }
// Priorytet waluty:  original (PLN/USD/EUR jako źródło) > conversion
// Priorytet typu:   permanent z kwotami → b2b z kwotami → dowolny z kwotami → pierwszy
function parseSalary(raw) {
  const types = raw.employmentTypes ?? raw.employment_types ?? [];
  if (types.length === 0) {
    return {
      salary_min:      raw.salary_from ?? raw.salaryFrom ?? null,
      salary_max:      raw.salary_to   ?? raw.salaryTo   ?? null,
      salary_currency: raw.currency    ?? null,
      salary_type:     null,
    };
  }

  // Filtruj do oryginalnej waluty (nie przeliczane) — żeby pokazać PLN, nie USD-converted
  const originals  = types.filter(e => e.currencySource === "original");
  const pool       = originals.length > 0 ? originals : types;

  const hasAmt = (e) => e.from != null || e.to != null;

  const preferred =
    pool.find(e => e.type === "permanent" && hasAmt(e)) ??
    pool.find(e => e.type === "b2b"       && hasAmt(e)) ??
    pool.find(e => hasAmt(e))                           ??
    pool[0];

  return {
    salary_min:      preferred.from     ?? preferred.fromPerUnit ?? null,
    salary_max:      preferred.to       ?? preferred.toPerUnit   ?? null,
    salary_currency: preferred.currency ?? null,
    salary_type:     preferred.type?.toLowerCase() ?? null,
  };
}

function mapPosting(raw) {
  const externalId = raw.slug ?? raw.id ?? null;
  const url        = externalId ? `https://justjoin.it/offers/${externalId}` : null;

  const city       = raw.city ?? null;
  const remoteType = parseWorkplaceType(raw.workplaceType ?? raw.workplace_type);
  let location;
  if (remoteType === "remote" && !city) location = "Remote";
  else if (city)                        location = city;
  else                                  location = null;

  const { salary_min, salary_max, salary_currency, salary_type } = parseSalary(raw);

  const skills    = raw.requiredSkills ?? raw.required_skills ?? raw.skills ?? [];
  const techStack = skills
    .map(s => (typeof s === "string" ? s : (s.name ?? s.skill ?? null)))
    .filter(Boolean);

  const seniority  = normalizeSeniority(raw.experienceLevel ?? raw.experience_level ?? raw.seniority ?? null);

  // JJit używa publishedAt + expiredAt (nie offer_validity)
  const postedAt   = raw.publishedAt    ?? raw.published_at   ?? null;
  const validUntil = raw.expiredAt      ?? raw.expired_at
                  ?? raw.offer_validity ?? raw.offerValidity   ?? null;

  return {
    source:          "justjoin",
    external_id:     externalId,
    url,
    title:           raw.title       ?? null,
    company:         raw.companyName ?? raw.company_name ?? raw.company?.name ?? null,
    location,
    remote_type:     remoteType,
    salary_min,
    salary_max,
    salary_currency,
    salary_type,
    tech_stack:      techStack,
    seniority,
    posted_at:       postedAt   ? new Date(postedAt).toISOString()   : null,
    valid_until:     validUntil ? new Date(validUntil).toISOString() : null,
    basic_payload:   raw,
  };
}

function mapJsonLdPosting(raw) {
  const url        = raw.url ?? null;
  const externalId = url ? url.split("/").filter(Boolean).pop() : null;
  const salary     = raw.baseSalary?.value ?? {};
  return {
    source:          "justjoin",
    external_id:     externalId,
    url,
    title:           raw.title                                ?? null,
    company:         raw.hiringOrganization?.name             ?? null,
    location:        raw.jobLocation?.address?.addressLocality ?? null,
    remote_type:     raw.jobLocationType === "TELECOMMUTE" ? "remote" : "office",
    salary_min:      salary.minValue  ?? null,
    salary_max:      salary.maxValue  ?? null,
    salary_currency: raw.baseSalary?.currency ?? null,
    salary_type:     null,
    tech_stack:      [],
    seniority:       null,
    posted_at:       raw.datePosted   ?? null,
    valid_until:     raw.validThrough ?? null,
    basic_payload:   raw,
  };
}

// ── Rekurencyjny finder ofert ─────────────────────────────────────────────────
function findInObject(obj, depth = 0) {
  if (!obj || typeof obj !== "object" || depth > 8) return null;
  for (const key of ["offers", "jobs", "jobOffers", "postings", "items", "results", "data"]) {
    if (Array.isArray(obj[key]) && obj[key].length > 0) {
      return {
        offers:     obj[key],
        totalCount: obj.totalCount  ?? obj.total_count ?? obj.count ?? obj.totalItems ?? null,
        totalPages: obj.totalPages  ?? obj.total_pages ?? null,
        pageSize:   obj.pageSize    ?? obj.per_page    ?? null,
      };
    }
  }
  for (const val of Object.values(obj)) {
    const found = findInObject(val, depth + 1);
    if (found) return found;
  }
  return null;
}

// ── Ekstrakcja danych z HTML ──────────────────────────────────────────────────
function extractFromHtml(html) {
  // Strategia 1: Next.js Pages Router — __NEXT_DATA__ (legacy)
  const nextDataMatch = html.match(
    /<script\b[^>]*\bid=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/i
  );
  if (nextDataMatch) {
    try {
      const state = JSON.parse(nextDataMatch[1]);
      const found = findInObject(state);
      if (found) return found;
    } catch (e) { /* fall through */ }
  }

  // Strategia 2: Next.js App Router — self.__next_f RSC chunks
  // Każdy push = oddzielny <script>; linia RSC: "rowHexId:{ json }"
  const scriptContents = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/gi)]
    .map(m => m[1].trim())
    .filter(c => c.includes("__next_f"));

  for (const chunk of scriptContents) {
    const pushMatch = chunk.match(/push\(\[\d+,"([\s\S]*)"\]\)\s*$/);
    if (!pushMatch) continue;

    const line = pushMatch[1]
      .replace(/\\"/g,  '"')
      .replace(/\\\\/g, "\\")
      .replace(/\\n/g,  "\n")
      .replace(/\\r/g,  "");

    const colonMatch = line.match(/^[0-9a-f]+:(\{[\s\S]*|\[[\s\S]*)$/);
    if (!colonMatch) continue;

    try {
      const obj   = JSON.parse(colonMatch[1]);
      const found = findInObject(obj);
      if (found) return found;
    } catch (e) { /* chunk nie zawierał ofert */ }
  }

  // Strategia 3: JSON-LD JobPosting (last resort)
  const jsonLdMatches = [...html.matchAll(
    /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi
  )];
  const jobs = [];
  for (const m of jsonLdMatches) {
    try {
      const obj   = JSON.parse(m[1]);
      const items = Array.isArray(obj) ? obj : [obj];
      for (const item of items) if (item["@type"] === "JobPosting") jobs.push(item);
    } catch (e) { /* skip */ }
  }
  if (jobs.length > 0) {
    return { offers: jobs, totalCount: null, totalPages: null, pageSize: null, isJsonLd: true };
  }

  return null;
}

// ── Debug payload ─────────────────────────────────────────────────────────────
function buildDebugPayload(html) {
  const ndMatch  = html.match(/<script\b[^>]*\bid=["']__NEXT_DATA__["'][^>]*>([\s\S]*?)<\/script>/i);
  const rscChunks = [...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/gi)]
    .map(m => m[1].trim())
    .filter(c => c.includes("__next_f"));

  let rscSample = null;
  for (const c of rscChunks) {
    const pm = c.match(/push\(\[\d+,"([\s\S]*)"\]\)\s*$/);
    if (pm && pm[1].length > 10) { rscSample = pm[1].substring(0, 600); break; }
  }

  const scriptIds = [...html.matchAll(/<script[^>]+id=["']([^"']+)["'][^>]*>/gi)].map(m => m[1]);

  return {
    html_length:         html.length,
    has_next_data:       !!ndMatch,
    rsc_chunk_count:     rscChunks.length,
    rsc_first_sample:    rscSample,
    script_ids:          scriptIds,
    html_start_2k:       html.substring(0, 2000),
    html_end_2k:         html.substring(Math.max(0, html.length - 2000)),
  };
}

// ── URL builder ───────────────────────────────────────────────────────────────
function buildUrl(cfg, page) {
  let base = "https://justjoin.it";
  if (cfg.location || cfg.category) {
    const loc = cfg.location ?? "all-locations";
    base += cfg.category ? `/job-offers/${loc}/${cfg.category}` : `/job-offers/${loc}`;
  }
  return page > 1 ? `${base}?page=${page}` : base;
}

// ── Główna logika ─────────────────────────────────────────────────────────────
async function scrapeJustJoin(cfg) {
  const results  = [];
  let page       = 1;
  let totalPages = null;

  const HEADERS = {
    "Accept":          "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "pl-PL,pl;q=0.9,en-US;q=0.8",
    "Accept-Encoding": "gzip, deflate, br",
    "User-Agent":      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
    "Cache-Control":   "no-cache",
  };

  while (true) {
    if (cfg.maxPages !== null && page > cfg.maxPages) break;

    const pageUrl = buildUrl(cfg, page);
    let html;
    try {
      html = await this.helpers.httpRequest({
        method:  "GET",
        url:     pageUrl,
        headers: HEADERS,
        json:    false,
      });
    } catch (err) {
      throw new Error(`JJit fetch error (page ${page}, url: ${pageUrl}): ${err.message}`);
    }

    if (typeof html !== "string") html = JSON.stringify(html);

    const extracted = extractFromHtml(html);

    if (!extracted || extracted.offers.length === 0) {
      if (page === 1) return [{ json: buildDebugPayload(html) }];
      break;
    }

    if (totalPages === null) {
      const pageSize = extracted.pageSize ?? extracted.offers.length;
      totalPages = extracted.totalPages
        ?? (extracted.totalCount ? Math.ceil(extracted.totalCount / pageSize) : page + 1);
    }

    for (const raw of extracted.offers) {
      const mapped = extracted.isJsonLd ? mapJsonLdPosting(raw) : mapPosting(raw);
      results.push({ json: mapped });
    }

    if (page >= (totalPages ?? page)) break;
    page++;
    if (cfg.delayMs > 0) await sleep(cfg.delayMs);
  }

  return results;
}

// ── Wejście n8n ───────────────────────────────────────────────────────────────
const trigger  = $input.first().json ?? {};
const userConf = trigger.config      ?? {};
const maxPages = trigger.max_pages   ?? userConf.maxPages ?? DEFAULT_CONFIG.maxPages;

const cfg = { ...DEFAULT_CONFIG, ...userConf, maxPages };

return await scrapeJustJoin.call(this, cfg);
